-- The one look both sinks draw: a hexagon outline centred in the icon, spinning.
--
-- The mark is ALWAYS our own Texture, on our own frame, so it takes a rotation and a vertex
-- colour. A count never draws the mark; it draws an OCCLUDER over it -- the subject's own
-- icon, centre-cropped -- because an inline escape takes a FontString's alpha and none of its
-- geometric transforms (security-taint-and-restricted-data.md §3.5).
-- Media/ is generated by tool/gen_media.py.

local _, ns = ...

local Look = {}
ns.Look = Look

Look.DEFAULT = "alarm"

--- The mark's side, as a fraction of the icon. It was 0.72 and is 0.53 because the mark reads
--- better small: a hexagon that nearly fills the icon competes with the art it is marking,
--- where one with air around it is a mark ON the icon. The plate is sized from this, so the
--- pair keeps its proportion wherever it goes.
--- ⚠ `OCCLUDE` does NOT follow it down. That crop was measured by eye against the ICON and is
--- only required to be above the widest thing drawn -- which is the plate, not the mark.
Look.FRACTION = 0.53
Look.SPIN_SECONDS = 3

--- MEASURED BY EYE on a live Essential row, which is the only oracle this has. It is above
--- FRACTION so the occluder covers the mark whole, and well inside the corners the Cooldown
--- Manager's mask rounds.
---
--- ⚠ Do NOT "improve" this by arithmetic. A search that minimised how far the drawn size has
--- to round picked 0.78125 over this, on the reasoning that its residual is six times smaller
--- -- and the result visibly RESIZED the icon where this does not. Whatever governs the
--- apparent scale of an inline escape, it is not that residual, and no model here predicts the
--- reading. `/sg tune crop <n>` is how a replacement gets chosen: on the real row, by looking.
Look.OCCLUDE = 0.82

--- Trim, in the FontString's own coordinate space, on the region's anchor rather than in the
--- escape -- the escape's own offsets are integers and this is not one.
---
--- MEASURED BY EYE: an escape centred in a FontString does not draw centred. At a 41-unit
--- draw in a 50-unit frame the art sits ~1.2 units LEFT of the region's centre, which is what
--- `SetPoint` puts back. Consistent with the escape claiming more advance width than its ink
--- fills, the excess trailing -- centring then centres the CLAIM and not the picture.
---
--- ⚠ It is NOT the drawn size rounding to a whole unit. That was the first theory and it is
--- dead: the shift survived a crop of 1.0, where the residual is exactly zero.
--- ⚠ OPEN: whether 1.2 is a constant in units or a fraction of the draw. One value cannot
--- tell them apart. Move the Edit Mode icon-size slider and look again -- if it still lands
--- the offset is constant, and if it drifts it belongs here as a ratio instead.
Look.OCCLUDE_X = 1.2
Look.OCCLUDE_Y = 0

--- Spell icons are 64x64 files. The crop is expressed to `CreateTextureMarkup` as fractions
--- and emitted by it as texels, so this is the number that converts between them.
local ICON_FILE_SIZE = 64

local PALETTE = {
  white = { 1.00, 1.00, 1.00 },
  yellow = { 1.00, 0.82, 0.25 },
  red = { 1.00, 0.32, 0.32 },
  green = { 0.43, 0.91, 0.50 },
  blue = { 0.38, 0.69, 1.00 },
  purple = { 0.77, 0.52, 1.00 },
  orange = { 1.00, 0.58, 0.25 },
  cyan = { 0.37, 0.92, 0.91 },
  --- The dark end of the `alarm` swing. Not a colour anyone would pick for a glow, and it is
  --- in the palette anyway because a cycle names its ends from here.
  black = { 0.02, 0.02, 0.02 },
}

--- A CYCLE is two colours a mark crosses between, and `alarm` crosses between the DARK and
--- BRIGHT ends of one hue rather than between two hues. Chroma is most of what peripheral
--- vision discards and luminance is most of what it keeps, so a swing between near-black and
--- yellow spends the whole budget on the channel that survives being seen out of the corner of
--- an eye. It also cannot be swallowed by the icon underneath: no spell art is both very dark
--- and very bright in the same place, so one end of the swing always stands off it.
---
--- ⚠ Vertex colour is written, not animated. The animation system has no colour type, and the
--- two ways to fake one both fail here: stacking two textures and crossfading their ALPHA
--- would fight the sealed bind for the one channel it owns, and a per-mark OnUpdate needs a
--- frame a texture does not have. So one shared ticker writes every cycling mark instead --
--- it draws and never evaluates, like the sealed families' own.
--- The period is bounded by the DECISION window, not by taste: a glance lasts about a GCD,
--- and at 1.6s the cycle completed 0.9 times in one -- so a look that landed in the dark phase
--- saw nothing at all, which is the exact failure the cycle exists to prevent. 0.6s puts two
--- and a half cycles in a 1.5s GCD, so no glance can miss the bright end.
--- 1.67 Hz, well under the 3 Hz where flashing starts to be a problem.
Look.CYCLE_SECONDS = 0.6

--- ...and the mark HOLDS each end rather than sweeping between them. A linear crossing spends
--- most of its time in the middle, which is a dim mustard -- neither end, and the least
--- visible of the three. Holding the ends and crossing fast maximises the duty cycle of the
--- swing: the mark is at one extreme 70% of the time and in between for 30%.
Look.CYCLE_CROSS = 0.15
local CYCLES = {
  alarm = { "black", "yellow" },
}

local cycling = setmetatable({}, { __mode = "k" })
local ticker

local function Lerp(a, b, t)
  return a + (b - a) * t
end

--- phase 0..1 -> blend 0..1, holding each end and crossing quickly between them.
local function Wave(phase)
  local cross = Look.CYCLE_CROSS
  local hold = (1 - 2 * cross) / 2
  if phase < hold then return 0 end
  if phase < hold + cross then return (phase - hold) / cross end
  if phase < 2 * hold + cross then return 1 end
  return 1 - (phase - 2 * hold - cross) / cross
end

local function Tick()
  local phase = (GetTime() % Look.CYCLE_SECONDS) / Look.CYCLE_SECONDS
  local t = Wave(phase)
  for mark, pair in pairs(cycling) do
    local from, to = PALETTE[pair[1]], PALETTE[pair[2]]
    mark:SetVertexColor(Lerp(from[1], to[1], t), Lerp(from[2], to[2], t),
      Lerp(from[3], to[3], t))
  end
  if next(cycling) == nil and ticker ~= nil then
    ticker:Cancel()
    ticker = nil
  end
end

--- Register a mark as cycling, or take it off. The single writer of a cycling mark's vertex
--- colour is `Tick`, so `SetLit` must hand the mark over rather than tinting it itself.
function Look.SetTint(mark, name)
  local pair = CYCLES[name]
  if pair == nil then
    cycling[mark] = nil
    local rgb = Look.Rgb(name)
    mark:SetVertexColor(rgb[1], rgb[2], rgb[3])
    return
  end
  cycling[mark] = pair
  if ticker == nil then ticker = C_Timer.NewTicker(0.05, Tick) end
end

function Look.IsColor(name)
  return PALETTE[name] ~= nil or CYCLES[name] ~= nil
end

function Look.Names()
  local names = {}
  for name in pairs(PALETTE) do names[#names + 1] = name end
  for name in pairs(CYCLES) do names[#names + 1] = name end
  table.sort(names)
  return names
end

--- A cycle has no single rgb, so anything that needs one -- a preview, a fallback -- takes the
--- BRIGHT end of the pair rather than the default, which may itself be a cycle. The bright end
--- and not the first: `alarm` starts at near-black, and a static mark drawn in the dark end is
--- a mark nobody can see.
local function Bright(pair)
  return PALETTE[pair[#pair]]
end

function Look.Rgb(name)
  local pair = CYCLES[name]
  if pair ~= nil then return Bright(pair) end
  return PALETTE[name] or (CYCLES[Look.DEFAULT] and Bright(CYCLES[Look.DEFAULT]))
    or PALETTE[Look.DEFAULT]
end

--- One white master, tinted per glow: every mark is our texture, so no hue needs its own file.
Look.MASTER = "Interface\\AddOns\\SmartGlo\\Media\\hex-white"

--- The PLATE: the same hexagon flooded solid, drawn UNDER the mark so the mark's dark phase is
--- dim against a known ground rather than against whatever the spell art happens to be there.
--- It TURNS WITH THE MARK -- same period, same direction, its own group started in the same
--- call -- so the two read as one object with a ground rather than as a mark sliding over a
--- backing. Two groups and not one because an animation applies to the region that owns its
--- group, and these are two textures.
Look.PLATE = "Interface\\AddOns\\SmartGlo\\Media\\hex-fill"

--- The plate's side, as a multiple of the MARK's. Wide enough that the mark has ground on every
--- side of it at every icon size; `FRACTION * PLATE_SCALE` = 0.742 stays inside `OCCLUDE`, which
--- it must, or a count's occluder would leave a plate peeking out below its threshold.
Look.PLATE_SCALE = 1.4

--- `purple` at 35% of its value: the same hue the palette offers, at a value that still reads as
--- a GROUND. Full `purple` is a light lavender whose relative luminance is 0.608 against
--- `yellow`'s 0.817 -- a 15% swing, which is the exact mistake the black-to-yellow cycle was
--- built to undo, and a plate in it would hand that mistake back as a background. At 35% the
--- plate is 0.213 and the swing above it is a Michelson 0.60.
Look.PLATE_RGB = { 0.27, 0.18, 0.35 }

--- ⚠ This number is BAKED INTO THE FILE by tool/gen_media.py, which reads it from this line. It
--- is not written at runtime, and it cannot be: `SetVertexColor`'s fourth argument and
--- `SetAlpha` are one channel -- `SetVertexColor` adds the aspects {VertexColor, Alpha} -- so
--- the alpha write that says whether the plate is drawn at all would clobber a translucency put
--- here, and the plate drew solid `[client 2026-09-11]`. The art carries it instead, so the one
--- `SetAlpha` per plate stays free for the value that may be secret.
Look.PLATE_ALPHA = 0.55

--- The occluder escape: `fileID` drawn at `fraction` of `width`, cropped to the same centred
--- fraction of the file, so it lands exactly over the pixels it is hiding. The Cooldown
--- Manager draws its icon untrimmed across the whole item rect -- there is no `SetTexCoord`
--- anywhere in Blizzard_CooldownViewer -- so the untrimmed baseline is 0..1 and this is the
--- whole arithmetic.
---
--- Sizes are in the FONTSTRING'S coordinate space, never screen pixels, so `width` must come
--- from `GetWidth()` on the frame the string is drawn in.
--- One candidate: the crop `half` texels either side of the file's centre, and what it costs
--- to draw at `width`. Both ends quantise -- the crop to whole TEXELS of a 64px file, the draw
--- to whole UNITS of the host frame, because `CreateTextureMarkup` emits every field with
--- `%d` -- so `residual` is how far the draw had to round. It is REPORTED, not minimised.
function Look.CropAt(width, half)
  local want = width * (2 * half) / ICON_FILE_SIZE
  local size = math.floor(want + 0.5)
  return { half = half, size = size, residual = size - want }
end

--- The crop in force. `residual` is reported rather than minimised -- it is a diagnostic the
--- probe prints, not a thing to optimise against (see OCCLUDE).
function Look.ChooseCrop(width)
  return Look.CropAt(width, math.floor(ICON_FILE_SIZE * Look.OCCLUDE / 2 + 0.5))
end

--- The crop is snapped to whole texels about the file's centre, so the crop's own centre is
--- exactly the file's and only the DRAW size can round.
--- `half` overrides the search with an explicit half-crop in texels; the probe passes one to
--- lay the search's pick beside its neighbours. Product code omits it.
function Look.IconEscape(fileID, width, half)
  local crop = half and Look.CropAt(width, half) or Look.ChooseCrop(width)
  local centre = ICON_FILE_SIZE / 2
  local lo = (centre - crop.half) / ICON_FILE_SIZE
  local hi = (centre + crop.half) / ICON_FILE_SIZE
  return CreateTextureMarkup(fileID, ICON_FILE_SIZE, ICON_FILE_SIZE, crop.size, crop.size,
    lo, hi, lo, hi, 0, 0), crop
end

--- How hard a mark presses, beyond being lit at all. `urgent` is the only level above plain
--- and it means "this one outranks the ordinary reading" -- a resource actively being wasted,
--- not merely a button that is available.
---
--- It PULSES rather than bounces, and the choice is not cosmetic: a translation is an offset
--- in absolute units, so it would need re-arming on every icon-size change -- the exact bug
--- class that left the mark at its old size until `OnSizeChanged` fixed it. A scale is
--- proportional and immune. The keyword says the MEANING so the drawing can be retuned
--- without touching a rule.
Look.PULSE_SECONDS = 0.45
Look.PULSE_SCALE = 1.35

function Look.Pulse(region)
  local group = region:CreateAnimationGroup()
  local out = group:CreateAnimation("Scale")
  out:SetScaleFrom(1, 1)
  out:SetScaleTo(Look.PULSE_SCALE, Look.PULSE_SCALE)
  out:SetDuration(Look.PULSE_SECONDS / 2)
  out:SetOrder(1)
  out:SetSmoothing("IN_OUT")
  local back = group:CreateAnimation("Scale")
  back:SetScaleFrom(Look.PULSE_SCALE, Look.PULSE_SCALE)
  back:SetScaleTo(1, 1)
  back:SetDuration(Look.PULSE_SECONDS / 2)
  back:SetOrder(2)
  back:SetSmoothing("IN_OUT")
  group:SetLooping("REPEAT")
  return group
end

--- One looping turn, armed at build and never started on a threshold. A count's crossing is
--- never observed; the mark simply spins under the occluder the whole time.
function Look.Spin(region)
  local group = region:CreateAnimationGroup()
  local rotation = group:CreateAnimation("Rotation")
  rotation:SetDegrees(-360)
  rotation:SetDuration(Look.SPIN_SECONDS)
  group:SetLooping("REPEAT")
  group:Play()
  return group
end
